package com.aivle.backend.journey;
import com.aivle.backend.common.entity.BaseEntity;import com.aivle.backend.project.entity.Project;import jakarta.persistence.*;import lombok.*;
@Entity(name="JourneyMarketingAsset") @Table(name="journey_marketing_assets") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED)
public class JourneyMarketingAsset extends BaseEntity{public enum Type{POSITIONING,CORE_MESSAGE,SLOGAN,SOCIAL_COPY,LANDING_HERO,EMAIL_COPY,CHANNEL_PLAN}@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="project_id",nullable=false)private Project project;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="concept_version_id",nullable=false)private ConceptVersion conceptVersion;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="workspace_id",nullable=false)private JourneyMarketingWorkspace workspace;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="generation_run_id",nullable=false)private JourneyMarketingGenerationRun generationRun;@Enumerated(EnumType.STRING)@Column(name="asset_type",nullable=false,length=30)private Type assetType;@Column(nullable=false)private int displayOrder;@Column(nullable=false)private boolean selected;public static JourneyMarketingAsset create(Project p,ConceptVersion c,JourneyMarketingWorkspace w,JourneyMarketingGenerationRun r,Type type,int order){JourneyMarketingAsset v=new JourneyMarketingAsset();v.project=p;v.conceptVersion=c;v.workspace=w;v.generationRun=r;v.assetType=type;v.displayOrder=order;return v;}public void select(boolean value){selected=value;}}
